function dateVal(d){return d||today()}function inRange(x,f,t){return (!f||x>=f)&&(!t||x<=t)}
function rangeDelivered(id,f,t){return db.sales.filter(x=>x.status==='Delivered'&&(!id||x.sr===id)&&inRange(x.date,f,t)).reduce((a,x)=>a+(+x.deliveredAmount||0),0)}
function rangeQty(id,f,t){return db.sales.filter(x=>x.status==='Delivered'&&(!id||x.sr===id)&&inRange(x.date,f,t)).reduce((a,x)=>a+(+x.qty||0),0)}
function zeroOutlets(id,f=month()+'-01',t=today()){let ids=id?[id]:srIds(),rows=[];ids.forEach(sid=>outlets(sid).forEach(o=>rows.push({...o,sr:sid})));let covered=new Set(db.sales.filter(x=>x.status==='Delivered'&&inRange(x.date,f,t)&&ids.includes(x.sr)&&(+x.deliveredAmount>0||+x.qty>0)).map(x=>x.sr+'|'+(x.outletCode||x.outletName)));return rows.filter(o=>!covered.has(o.sr+'|'+(o.code||o.name)))}function zeroCount(id,f=month()+'-01',t=today()){return zeroOutlets(id,f,t).length}
function fileData(file,max=1800000){return new Promise((res,rej)=>{if(!file)return res('');if(file.size>max)return rej(new Error('File too large. Keep under '+Math.round(max/1000000*10)/10+' MB.'));let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)})}
