let outMap={};db.sales.filter(x=>ids.includes(x.sr)&&x.status==='Delivered'&&inRange(x.date,f,to)).forEach(x=>{let k=x.outletName||x.outletCode||'Outlet';outMap[k]=(outMap[k]||0)+(+x.deliveredAmount||0)});let tops=Object.entries(outMap).sort((a,b)=>b[1]-a[1]).slice(0,5),topMax=Math.max(1,...tops.map(x=>x[1]));
